// Sample scenarios for the demo provider. Each one is a fixed, hand-written example: a feedback
// line, a short summary, two or three plausible readings with concrete steps, and (only when the
// feedback is genuinely ambiguous) questions to ask. Nothing here is generated by AI.

export interface Reading {
  label: string;
  /** What the feedback might mean. A possibility, never a fact. */
  meaning: string;
  /** What to look for in the design to test this reading. */
  issues: string[];
  /** Specific next steps a designer can follow. */
  tries: string[];
  why: string;
}

export interface Scenario {
  id: string;
  /** Short label for the picker. */
  title: string;
  /** The sample feedback the picker fills in. */
  feedback: string;
  /** Typed feedback is routed here by these patterns (score = hits x weight; best score wins). */
  patterns: RegExp[];
  weight: number;
  summary: string;
  assumptions: string[];
  readings: Reading[];
  /** Empty when the feedback is specific enough to act on. */
  questions: string[];
}

