export interface SampleScenario {
  id: string;
  title: string;
  feedback: string;
}

/** What the picker shows. */
export const SAMPLE_SCENARIOS: SampleScenario[] = SCENARIOS.map(({ id, title, feedback }) => ({ id, title, feedback }));

const normalise = (text: string) =>
  text
    .trim()
    .toLowerCase()
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/\s+/g, ' ')
    .replace(/[.!?\s]+$/, '');

/**
 * The scenario that fits `feedback`, or null when the demo has none. A sample's own text always
 * matches it. Otherwise patterns score by hits x weight, specific scenarios outrank vague ones on
 * a tie, and a comment that hits nothing gets no scenario rather than a generic one.
 */
export function matchScenario(feedback: string): Scenario | null {
  const text = normalise(feedback);
  const exact = SCENARIOS.find((s) => normalise(s.feedback) === text);
  if (exact) return exact;
  let best: Scenario | null = null;
  let bestScore = 0;
  for (const s of SCENARIOS) {
    const score = s.patterns.filter((p) => p.test(text)).length * s.weight;
    if (score > bestScore) {
      best = s;
      bestScore = score;
    }
  }
  return best;
}
